class Portfolio:
    def __init__(self, client: Cru) -> None:
        self._client = client

    def list(
        self,
        *,
        lwin: Union[str, Sequence[str], None] = None,
        wine_name: Optional[str] = None,
        current_location_code: Union[str, Sequence[str], None] = None,
        deliverable_warehouse_code: Union[str, Sequence[str], None] = None,
        stock_type: Union[str, Sequence[str], None] = None,
        stock_status: Union[str, Sequence[str], None] = None,
        duty_paid: Optional[bool] = None,
        condition_status: Union[str, Sequence[str], None] = None,
        is_listed: Optional[bool] = None,
        limit: Optional[int] = None,
        offset: Optional[int] = None,
        extra_query: Optional[Dict[str, Any]] = None,
    ) -> Page[models.PortfolioWine]:
        """Retrieve your portfolio.

        The wine you hold, by wine: where each unit is, its status, condition and cost, any
        listing, and each wine’s market price, lowest offer and highest bid.

        **Filters narrow each wine too.** wine_name, current_location_code,
        deliverable_warehouse_code, stock_type, stock_status, duty_paid and condition_status
        combine with each other and with lwin. They choose the portfolio lines shown inside each
        wine, as well as which wines appear.

        **A corporate supplier’s own stock.** A corporate supplier also sees its own offers, as
        stock_type supplier, and its stock on broking purchase orders, as stock_type bpo. Both
        are always due_in, as market offers show them: the stock reaches Cru only once it is
        sold. Neither has a cost or can be sold into a bid. Cru takes no commission from a
        supplier, and adds its margin for buyers instead, so both are listed at what the
        supplier is paid: pricing.listing_price and pricing.net_proceeds are each the supplier’s
        own price or, for BPO stock, the purchase order’s cost, and commission_percent,
        commission and settlement_fee are 0.0. Its own offers are in “Your warehouse”, of
        warehouse.location_type supplier. BPO stock is named after the purchase order’s supplier
        warehouse, of warehouse.location_type inbond with its IB_ current_location_code, or is
        in “Your warehouse” when the order names none. Both always have a
        warehouse.deliverable_warehouse_code: the Cru warehouse they go to once sold, which for
        stock at the supplier’s own warehouse is the Cru warehouse in its country, as market
        offers show it.

        Scope: portfolio:read.

        Returns one page; auto_paging_iter() walks every page.

        Args:
            lwin: Only these wines: up to 20 comma-separated 18-digit LWIN18 codes.
            wine_name: Only wines whose name contains every word given, as GET /wines matches a
            name, such as “Lafite 2010”: one to six words of two or more characters. Anything
            else is refused with VALIDATION_INVALID_VALUE.
            current_location_code: Only portfolio lines of wine stored now at any of these, as
            warehouse.current_location_code gives them, comma-separated, such as
            UK_DRAK,IB_20,ADDR_123: a Cru warehouse code (UK_DRAK, HK_KERRY, SG_TOLL,
            FR_DARTESS, US_NAPA), IB_ and the inbond_address_id of an inbond warehouse outside
            Cru, or ADDR_ and the id of your own address. Case-insensitive. Unlike
            deliverable_warehouse_code, it says where the wine is, not where it is delivered
            from. An ADDR_ code that is not one of your addresses matches nothing. Anything else
            is refused with VALIDATION_INVALID_VALUE.
            deliverable_warehouse_code: Only portfolio lines whose
            warehouse.deliverable_warehouse_code is any of these Cru warehouses, comma-
            separated: UK_DRAK, HK_KERRY, SG_TOLL, FR_DARTESS, US_NAPA. An unknown code is
            refused with VALIDATION_INVALID_VALUE.
            stock_type: Only portfolio lines of these stock types, comma-separated, such as
            cru,external. A stock_type is cru, external, supplier or bpo, and only a corporate
            supplier has the last two. Any other value is refused with
            VALIDATION_UNSUPPORTED_VALUE.
            stock_status: Only portfolio lines with any of these stock_status values, comma-
            separated: in_stock, in_transit or due_in. Case-insensitive. It matches the
            stock_status each line shows, so a supplier’s own offers and its BPO stock are
            due_in. Any other value is refused with VALIDATION_UNSUPPORTED_VALUE.
            duty_paid: true for only the portfolio lines whose duty is paid; false for only
            those whose duty is not. Omit it for both. Default: both.
            condition_status: Only portfolio lines with any of these condition_status values,
            comma-separated: verified, client_reserves or apd. Case-insensitive. A line with no
            condition_status matches none of them. Any other value is refused with
            VALIDATION_UNSUPPORTED_VALUE.
            is_listed: true for only the portfolio lines listed for sale, as GET /offers gives
            them; false for only those that are not. Omit it for both. Default: both.
            limit: Number of wines to return. A larger value is refused with
            VALIDATION_INVALID_VALUE, not reduced.
            offset: Number of wines to skip.
            extra_query: Query parameters this version does not know yet, sent as given.
        """
        return self._client._call(_OPS['listPortfolio'], {}, {'lwin': lwin, 'wine_name': wine_name, 'current_location_code': current_location_code, 'deliverable_warehouse_code': deliverable_warehouse_code, 'stock_type': stock_type, 'stock_status': stock_status, 'duty_paid': duty_paid, 'condition_status': condition_status, 'is_listed': is_listed, 'limit': limit, 'offset': offset, **(extra_query or {})}, None)


class Trades:
    def __init__(self, client: Cru) -> None:
        self._client = client

    def list_purchases(
        self,
        *,
        lwin: Union[str, Sequence[str], None] = None,
        status: Union[str, Sequence[str], None] = None,
        sort: Optional[str] = None,
        direction: Optional[str] = None,
        limit: Optional[int] = None,
        offset: Optional[int] = None,
        extra_query: Optional[Dict[str, Any]] = None,
    ) -> Page[models.Purchase]:
        """List your purchases.

        What you have bought on Cru, by order line, newest first, with each order’s status,
        invoice and units.

        **The order and invoice links are for the customer.** order_url and invoice_url are
        pages on the Cru site the order was placed on, for the customer signed in there: an API
        key or access token does not open them. Show them to the customer rather than fetching
        them.

        Scope: trades:read.

        Returns one page; auto_paging_iter() walks every page.

        Args:
            lwin: Only these wines: up to 20 comma-separated 18-digit LWIN18 codes.
            status: Only order lines with a unit in any of these states, comma-separated, in any
            case: in_portfolio, for_sale, sold, in_transit or delivered, as units[].status gives
            them. A line with no units stored with Cru matches none. Anything else is refused
            with VALIDATION_UNSUPPORTED_VALUE.
            sort: What to order by: traded_at, the date of the order, the only choice.
            direction: desc for newest first, or asc for oldest first.
            limit: Number of purchases to return. A larger value is refused with
            VALIDATION_INVALID_VALUE, not reduced.
            offset: Number of purchases to skip.
            extra_query: Query parameters this version does not know yet, sent as given.
        """
        return self._client._call(_OPS['listPurchases'], {}, {'lwin': lwin, 'status': status, 'sort': sort, 'direction': direction, 'limit': limit, 'offset': offset, **(extra_query or {})}, None)

    def list_sales(
        self,
        *,
        lwin: Union[str, Sequence[str], None] = None,
        status: Union[str, Sequence[str], None] = None,
        deliverable_warehouse_code: Union[str, Sequence[str], None] = None,
        sort: Optional[str] = None,
        direction: Optional[str] = None,
        limit: Optional[int] = None,
        offset: Optional[int] = None,
        extra_query: Optional[Dict[str, Any]] = None,
    ) -> Page[models.Sale]:
        """List your sales.

        What you have sold on Cru, one unit at a time, newest first: commission, what you
        received and profit.

        **One sale per unit.** Each unit sold is its own sale, with quantity 1, its cru_id and
        no order number. sold_price, commission and settlement_fee take the sale down to
        net_proceeds, what you received, and profit_loss sets that against cost.

        **Wine held outside Cru, on its way to Cru.** Once it sells, wine held outside Cru goes
        to the Cru warehouse deliver_to names, by deliver_by. status says how far it has got:
        transfer_needed until a transfer to Cru is booked, then awaiting_transfer, with
        transfer_ref naming the transfer; on_purchase_order while it is due in on a purchase
        order; and delivered_to_cru once it is there. Wine stored with Cru has no deliver_to,
        and is always delivered_to_cru.

        Scope: trades:read.

        Returns one page; auto_paging_iter() walks every page.

        Args:
            lwin: Only these wines: up to 20 comma-separated 18-digit LWIN18 codes.
            status: Only sales in any of these states, comma-separated, in any case:
            transfer_needed, awaiting_transfer, on_purchase_order or delivered_to_cru. Anything
            else is refused with VALIDATION_UNSUPPORTED_VALUE.
            deliverable_warehouse_code: Only sales of wine held outside Cru going to any of
            these Cru warehouses, comma-separated: UK_DRAK, HK_KERRY, SG_TOLL, FR_DARTESS,
            US_NAPA. Wine stored with Cru matches none. An unknown code is refused with
            VALIDATION_INVALID_VALUE.
            sort: What to order by: traded_at, the date of the sale, the only choice.
            direction: desc for newest first, or asc for oldest first.
            limit: Number of sales to return. A larger value is refused with
            VALIDATION_INVALID_VALUE, not reduced.
            offset: Number of sales to skip.
            extra_query: Query parameters this version does not know yet, sent as given.
        """
        return self._client._call(_OPS['listSales'], {}, {'lwin': lwin, 'status': status, 'deliverable_warehouse_code': deliverable_warehouse_code, 'sort': sort, 'direction': direction, 'limit': limit, 'offset': offset, **(extra_query or {})}, None)


